insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('114-3301-006','114-3301',6,'single_choice','甲基於買賣契約，得請求乙支付價金，共新臺幣（下同）30 萬元。若甲將對乙之30 萬元價金債權出 賣於丙，下列敘述，何者正確？','甲原則上應對丙擔保乙之支付能力','若乙於訂立買賣契約時，已為受監護宣告者，善意之丙得請求甲負擔權利瑕疵擔保責任','若乙無法對丙提出給付，甲應負擔代為履行之責','甲將對乙之債權出賣於丙，應於甲通知丙後，始生效力','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-3301-007','114-3301',7,'single_choice','民法關於主權利與從權利之規定，下列敘述，何者正確？','以抵押權擔保之債權，其請求權已因時效而消滅，如抵押權人，於消滅時效完成後，3 年間不實行 其抵押權者，其抵押權消滅','以留置權擔保之債權，其請求權已因時效而消滅，如留置權人，於消滅時效完成後，5 年間不實行 其留置權者，其留置權消滅','讓與債權時，該債權之擔保及其他從屬之權利，一律隨同移轉於受讓人','以質權擔保之債權，其請求權雖經時效消滅，質權人仍得就其質物取償','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-3301-008','114-3301',8,'single_choice','甲欲出售其所有之A 屋，遂委託房屋仲介商乙代為銷售。某日，乙帶領丙前來賞屋完畢後，丙甚為喜 歡，表示願以新臺幣（下同）1500 萬元購屋之意願；離去之際，適逢甲前來查看售屋狀況，甲、乙、 丙三人簡單寒暄後，便各自離開。嗣後，甲透過友人得知丙之聯絡方式，遂聯繫丙向其表示願意減價 50 萬，直接出售A 屋於丙，以避免雙方支付高額仲介費。下列敘述，何者錯誤？','甲委託仲介銷售之契約，性質上乃屬於居間，係為他方報告訂約之機會或為訂約之媒介，故其既不 屬隱名代理，亦不屬雙方代理','乙為媒介居間人，僅以契約因其媒介而成立時，始得請求報酬，故若甲、丙自行訂立買賣契約時， 乙無從請求甲、丙支付仲介報酬','甲自行聯繫丙並與其訂立買賣契約，該當於民法第101 條第1 項視為條件已成就之情形，故甲、丙 二人仍應給付仲介報酬於乙','甲故意拒絕因乙媒介而成立之契約，而自行與丙訂立同一內容之契約者，應認為違反誠信原則','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-3301-009','114-3301',9,'single_choice','甲於2024 年6 月6 日向丙汽車商購買一款新車。不料於2025 年1 月1 日元旦與好友乙出遊時，新車 突然發生暴衝，甲雖及時緊踩煞車，仍發生車禍意外，造成甲與乙皆因衝撞而受傷。事故後，新車嚴 重撞毀已不值得修繕，甲乙受傷住院。經事故鑑定報告，汽車暴衝係因該款汽車系統程式瑕疵問題所 致，而甲於汽車暴衝時之處置，並無過失。下列敘述，何者錯誤？','因汽車系統程式瑕疵導致汽車暴衝，屬無法即知之瑕疵問題，丙汽車商仍負物之瑕疵擔保責任','汽車暴衝係因其系統程式瑕疵問題，汽車商丙對甲可能同時負有不完全給付責任與物之瑕疵擔保責任','甲、乙所受之身體傷害，皆不得依民法規定請求固有利益之損害賠償','甲、乙所受之身體傷害，屬瑕疵結果損害，得依民法規定，請求損害賠償','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-3301-010','114-3301',10,'single_choice','受監護宣告之甲，由其父母任監護人。某日，甲於公園中遊玩，在垃圾桶中發現一台無人所有之玩具 飛機，遂拾起把玩許久。嗣後，就讀國小三年級之乙見狀，便央求甲將該玩具飛機贈送於己，甲便欣 然同意。甲隔日再於公園遇見乙，兩人便共同玩著射飛機，遊玩間，孰料玩具飛機不慎飛射撞上坐在 公園休息之遊民丙，丙頭部因此受傷，而向兩人之父母求償醫療費及精神慰撫金。下列敘述，何者 錯誤？','甲拾得玩具飛機據為己有，屬一事實行為，故甲取得該玩具飛機之所有權','甲贈與乙玩具飛機之行為，對乙而言，屬純獲法律上利益，故該贈與契約有效','甲、乙二人遊玩間因飛機誤射而令丙頭部受傷，原則上屬甲、乙兩人共同侵害丙之身體健康權','甲、乙與其二人之父母原則上對丙負損害賠償責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-3301-011','114-3301',11,'single_choice','甲與中古車商乙訂立買賣契約，向乙購買A 車。乙之業務員丙明知該車曾經發生車禍，卻向甲偽稱該 車未遭車禍，致甲決定訂約。關於買賣契約之效力，下列敘述，何者正確？','買賣契約無效','買賣契約效力未定','甲得撤銷購買A 車之意思表示','以乙明知其事實或可得而知者為限，甲始得撤銷','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-3301-012','114-3301',12,'single_choice','甲為臺南市某歐洲進口傢俱公司，乙之女兒即將結婚，婚後住在臺北市，乙到甲公司門市部購買並指 定A 進口傢俱為其女兒嫁妝，甲公司表明該公司在臺南市是免費送到府，並以臺南市為清償地，無送 外縣市之服務。經甲與乙雙方討論後，改以臺北市作為交付處所，由甲委託並交付A 傢俱於丙貨運公 司運送。運送途中，因為高速公路連環車禍，該批傢俱因此滅失，對此連環車禍，丙貨運公司之駕駛 並無過失。下列敘述，何者錯誤？','該進口傢俱於運送途中車禍，致A 傢俱滅失，屬給付不能','依民法第373 條有關危險負擔之規定，A 傢俱滅失之風險尚未移轉於乙，乙得請求甲重新交付新傢俱','在甲將傢俱交付於丙貨運公司運送時，A 傢俱滅失之風險已移轉於乙，乙不得請求返還價金','乙得請求甲讓與其對車禍肇事者之損害賠償請求權','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-3301-013','114-3301',13,'single_choice','甲、乙、丙合夥成立一家民宿，甲、乙為出名營業人，丙為隱名合夥人，下列關於甲、乙、丙間合夥 契約終止之敘述，何者正確？','丙死亡時，丙之隱名合夥契約當然終止','丙受監護宣告時，丙與甲、乙間之隱名合夥契約當然終止','隱名合夥契約終止時，丙之出資因損失而減少者，僅返還其餘存額','隱名合夥契約終止後，甲、乙、丙間之合夥關係，即生解散之效力','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-3301-014','114-3301',14,'single_choice','乙經營A 餐廳，受新冠疫情衝擊，該餐廳生意受到嚴重影響，於是與甲訂立消費借貸契約。為確保乙 對甲新臺幣（下同）2000 萬元債務之清償，甲要求乙提供擔保，乙提供自己所有A 餐廳之不動產所 有權，為甲之債權設定普通抵押權，並委任其好友丙，提供連帶保證。但乙最終仍因經營不善，將其 所經營之A 餐廳全部（包含乙對甲之債務）轉讓於丁。嗣後，丁因投資股票不利而破產，甲直接向丙 請求3000 萬債務之履行，但甲拋棄對A 餐廳之抵押權。下列敘述，何者正確？','基於物保優先原則，丙得向甲主張，甲應先就乙自己所提供之A 餐廳物權擔保行使抵押權','甲雖得向丙請求債務之清償，但丙得對甲行使先訴抗辯權','連帶保證人對債權人清償後，不得承受債權人對主債務人之債權','丙得主張，丁承擔乙之債務時，並未事先經其同意，其保證債務已因債務之承擔而消滅','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-015','114-3301',15,'single_choice','甲向乙購買商品一批轉賣於丙，甲、乙雙方約定付款之期限為：「丙付款於甲後，甲應立即支付貨款 於乙」。嗣後，丙因經營不善倒閉而未能支付貨款於甲。下列敘述，何者正確？','甲、乙之約定，不影響雙方之買賣契約之效力，乙仍得隨時請求甲付款','丙之付款為甲付款於乙之條件，因丙倒閉致條件不成就，乙不得請求甲付款','丙之付款為甲付款於乙之不確定期限，於丙倒閉時，甲應付款於乙之清償期屆至','丙之付款為甲付款於乙之不確定期限，於丙倒閉時，甲應即對乙負給付遲延責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-016','114-3301',16,'single_choice','甲將A 屋出租於乙，每月租金新臺幣（下同）4 萬元，並由乙交付5 萬元押租金於甲。下列敘述，何 者正確？','押租金與租賃契約為個別獨立之契約，租賃契約消滅，押租金契約原則上不隨同消滅','押租金與租賃契約為個別獨立之契約，租賃契約之成立，不以押租金之交付為要件','押租金具有擔保租賃債務之功能，屬於民法上法定擔保物權','押租金契約原則上為諾成契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-017','114-3301',17,'single_choice','甲、乙、丙共同出資合夥經營A 飲料店，因購買原料積欠丁債務。下列敘述，何者正確？','丁得逕請求甲、乙、丙、A 負連帶清償責任','丁得逕請求甲、乙、丙負連帶清償責任','丁僅得向A 請求清償債務','A 之財產不足清償對丁之債務時，丁始得請求甲、乙、丙負連帶清償責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-018','114-3301',18,'single_choice','買受人就買賣標的物之瑕疵，主張基於物之瑕疵擔保責任與不完全給付之債務不履行責任而解除契 約。下列敘述，何者錯誤？','二者均以出賣人就物之瑕疵有故意或過失者，買受人始得解除契約','瑕疵可補正者，主張不完全給付之買受人，須於催告出賣人補正而其不補正時，始得解除契約','買受人向出賣人主張物有瑕疵者，出賣人得定相當期限，催告買受人於其期限內是否解除契約','依物之瑕疵擔保責任而解除契約顯失公平之情形，買受人仍得依不完全給付之規定而解除契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-019','114-3301',19,'single_choice','甲有A 建地，並登記為A 地所有人。乙未經甲之同意，無權占有A 地建屋居住長達25 年之久。甲移 居海外，不知乙無權占用A 地一事，未曾請求乙返還A 地。下列敘述，何者正確？','關於消滅時效之規定，適用於A 地返還請求權','乙得因時效取得，請求登記為A 地之地上權人','乙因時效取得A 地所有權而免除占用A 地之損害賠償責任','乙得時效取得A 地租賃權','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-020','114-3301',20,'single_choice','甲、乙與丙合夥經營事業，A 地乃合夥財產，合夥股份各三分之一。甲未經乙與丙同意，將A 地出租 且交付於丁占有。下列敘述，何者正確？','乙與丙均得單獨請求丁返還A 地於自己','乙與丙均僅得共同請求丁返還A 地於甲','乙與丙均得共同請求丁返還A 地於乙與丙','乙與丙均得單獨請求丁返還A 地於甲、乙與丙全體','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-3301-021','114-3301',21,'single_choice','甲之A 地與乙之B 地相鄰，兩地均與公路有適宜聯絡，甲於民國80 年起，於A 地設置道路供自己快 速直接通行至公路，並同意乙使用該道路通行。因該道路未設柵欄，雖甲已在路口設置私人道路告示， 惟仍有不少民眾為方便而通行該道路。丙市府為維公眾通行安全，在該道路舖設柏油路面，並劃設交 通標線。下列敘述，何者正確？','乙得甲同意通行使用該道路，即成立不動產役權，乙亦得於該道路上設置廣告看板','乙得依鄰地通行權之相鄰關係，通行使用系爭道路','丙若在系爭道路範圍內之私有土地均辦理徵收，但因認定該道路已成為既成道路有公用地役關係， 而以命令規定繼續使用，得不予同時徵收補償','如無特別法令依據，於該私設道路已符合司法院釋字第400 號解釋意旨所稱既成道路前，甲非不得 請求予以除去丙之道路維護行為','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-022','114-3301',22,'single_choice','甲有A 轎車，乙有B 轎車，二車同廠牌同類型。A 轎車之引擎故障，甲取B 轎車之引擎，裝在A 轎 車上。甲與丙訂立買賣契約，將A 轎車（裝有B 轎車之引擎）出賣於惡意之丙，並以移轉所有權之 意思交付於丙。關於B 轎車引擎之所有權歸屬，下列敘述，何者正確？','歸屬於乙所有','歸屬於甲所有','歸屬甲、丙共有','歸屬乙、丙共有','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-023','114-3301',23,'single_choice','甲與乙分別共有A 地，應有部分各二分之一，並登記於土地登記簿。甲與乙就共有之A 地並未成立 分管契約。甲以其應有部分設定普通抵押權於丙。嗣後乙向法院提起裁判分割共有物之訴。下列敘述， 何者正確？','甲與乙應經共有人全體之同意，始得訴請分割A 地','自共有物分割效力發生時起，各共有人得請求其他共有人移轉其分得部分之所有權','若法院之確定分割判決，變價分配於甲，則丙之抵押權因抵押物滅失而消滅','若丙經訴訟告知，則其抵押權移存於甲分得之部分','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-024','114-3301',24,'single_choice','甲與乙訂立A 地之借名登記契約，由甲將自丙所購買之A 地所有權直接移轉登記於乙，以節省稅賦。 乙未經甲同意，竟將A 地出賣於善意不知該借名登記情事之丁，並已完成所有權移轉登記。依法院實 務見解，下列敘述，何者正確？','不動產借名登記契約為借名人甲與出名人乙間之物權契約','乙將A 地移轉登記於丁之處分行為，為有權處分','乙將A 地移轉登記於丁之處分行為，因係無權處分，其效力未定','甲若不欲承認乙之處分行為，得起訴主張乙違反委任契約，並代位乙請求丁塗銷A 地登記返還於乙','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-025','114-3301',25,'single_choice','下列關於普通地上權之敘述，何者正確？','地上權設定時，不以地上建築物或工作物之存在為必要，設定後亦不因建築物或工作物之滅失而消滅','未定期限而有支付地租約定之地上權，地上權人依法應於支付未到期之3 年分地租後，始得拋棄其 權利','地上權設定後，因不可抗力妨礙其土地之使用，依原定地租給付顯失公平者，地上權人得請求法院 減免之','因不可歸責於地上權人之事由，致土地不能達原來使用之目的時，地上權當然消滅','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-026','114-3301',26,'single_choice','依現行民法規定，下列關於地上權之敘述，何者正確？','在他人土地上種植竹木而使用其土地者，得設定普通地上權','普通地上權不得約定超過30 年，超過者縮短為30 年','普通地上權人就土地之使用收益有約定使用方法者，關於該方法之約定，非經登記，不得對抗第三人','區分地上權人與其設定之土地上下有使用、收益權利之人，約定相互間使用收益之限制時，如未得 土地所有人同意者，該約定無效','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-027','114-3301',27,'single_choice','下列何者非屬權利質權設定之標的？','股份有限公司股票','普通抵押權所擔保之債權','清光緒年間所製造發行之大清銀幣','著作財產權','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-3301-028','114-3301',28,'single_choice','甲係經許可以受質為營業者，乙為借錢而移轉占有其首飾項鍊於甲，俾擔保甲之債權受償。乙屆期無 力償債，未於取贖期間屆滿後5 日內，取贖其首飾項鍊。下列敘述，何者正確？','甲不得請求乙清償債務','甲應於拍賣該首飾項鍊前通知乙','甲得就首飾項鍊行使其權利，但所擔保之債權，若未全額受償，不足清償部分之債權，仍未消滅','甲對乙負有清算義務，甲須經清算，始取得首飾項鍊之所有權','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-029','114-3301',29,'single_choice','甲將其土地設定普通抵押權於乙，嗣後甲將該土地設定普通地上權於丙建築房屋。屆期甲未清償債務， 乙實行抵押權而無人應買。關於丙房屋之處置，下列敘述，何者正確？','甲非經抵押權人乙之同意，不得設定地上權於丙建築房屋，故乙得請求丙拆屋還地','因可歸責於甲之事由致土地價值減少時，乙得因此主張實行抵押權，拍賣抵押物','乙於必要時，得聲請法院將房屋與土地併付拍賣，但對房屋賣得價金不得主張優先受清償','乙得主張基於物權優先效力，先設定之抵押權效力及於地上權及地上房屋，一併拍賣而優先受清償','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-030','114-3301',30,'single_choice','甲有登記其名下之A 地及A 地上之B 屋，甲僅以B 屋設定典權於乙，約定期限20 年，並附有到期 不贖即作絕賣之條款，但該條款未經登記。嗣後，甲將A 地讓售於丙，並完成所有權移轉登記。甲於 典期屆滿後，不以原典價回贖。下列敘述，何者錯誤？','甲於典期屆滿後，不以原典價回贖，乙不負清算義務，即取得B 屋所有權','甲於典期屆滿後，不以原典價回贖，乙、丙間推定有租賃關係','甲於典期屆滿後，不以原典價回贖，縱使絕賣條款未經登記，乙仍取得B 屋所有權','甲於典期屆滿後，不以原典價回贖，丙訴請乙拆除B 屋返還土地，並無理由','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-031','114-3301',31,'single_choice','甲為A 車所有人，A 車乃古董車，全車原廠維修，且已報廢登記車籍。乙竊得A 車，半年後，乙因 酒駕致A 車毀損。下列敘述，何者錯誤？','甲請求乙返還占有A 車之使用利益，有理由','甲請求乙賠償因A 車毀損所受之損害，有理由','若乙於占有期間為A 車整車之車體鍍金，則其請求該筆費用，有理由','若乙竊得A 車後，隨即出賣且交付A 車於丙。丙不知A 車乃贓車，且就其不知無過失，則甲請求 乙賠償因此所受之損害，有理由','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-032','114-3301',32,'single_choice','成年年齡由20 歲下降至18 歲，影響有關未成年人所為或所受身分行為之規定。下列關於民法規定之 敘述，何者正確？','夫妻之一方收養他方子女時，應長於被收養者16 歲以上','未成年人結婚，應得法定代理人之同意','收養者之年齡，應長於被收養者18 歲以上','男未滿17 歲，女未滿15 歲者，不得訂定婚約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-033','114-3301',33,'single_choice','甲男與乙女為夫妻，於婚姻期間，甲與丙女外遇，乙亦與丁男外遇。下列敘述，何者錯誤？','乙得向法院請求與甲離婚','乙因判決離婚生活陷於困難，得向法院請求甲給付相當之贍養費','乙不得因判決離婚請求所受之非財產上之損害賠償','若甲、乙為協議離婚，並未為贍養費之約定，雙方亦不得再向法院請求贍養費之給付','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-034','114-3301',34,'single_choice','甲男與乙女結婚後，因甲登山失蹤滿7 年，法院依聲請為甲死亡宣告之裁定。嗣後，乙女與丙男結婚， 而甲卻在乙、丙婚後生存歸來，法院為撤銷甲死亡宣告之裁定。關於乙之婚姻關係，下列敘述，何 者正確？','乙、丙雙方均善意時，乙、丙之後婚有效，甲、乙之前婚消滅','乙、丙中一人善意時，乙、丙之後婚有效，甲、乙之前婚消滅','不論乙、丙是否善意，乙、丙之後婚有效，甲、乙之前婚消滅','由乙決定甲、乙前婚或乙、丙後婚有效','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-3301-035','114-3301',35,'single_choice','甲男乙女原為夫妻，於協議離婚時，約定由甲單獨行使或負擔未成年子女丙之權利、義務。嗣後，因 丙考上知名高中，甲之父親丁贈送名牌A 腳踏車一輛於丙。下列敘述，何者錯誤？','甲依法有權管理丙之A 腳踏車','甲依法得自由處分丙之A 腳踏車','甲依法有權使用丙之A 腳踏車','甲依法不須取得乙之同意，即得單獨管理丙之A 腳踏車','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-036','114-3301',36,'single_choice','下列何種情事，依民法規定，不得請求法院酌定之？','父母於子女出生登記前，就子女從父姓或母姓約定不成','父母對於未成年子女重大事項權利之行使意思不一致','夫妻之住所協議不成','夫妻離婚時，對於未成年子女權利義務之行使或負擔協議不成','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-037','114-3301',37,'single_choice','下列何者非屬剩餘財產分配之範圍？','夫或妻婚前財產，於婚姻關係存續中所生之孳息','夫或妻婚後無償取得之財產，於婚姻關係存續中所生之孳息','夫或妻於婚姻關係存續中，改用法定財產制前所得之薪資','夫或妻於婚姻關係存續中，對他方所生之一般債權','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-038','114-3301',38,'single_choice','依民法規定，關於法院成立之調解離婚，婚姻關係於何時消滅？','法院調解離婚成立時消滅','法院向戶政機關為調解離婚成立通知時消滅','一方當事人向戶政機關為離婚登記時消滅','雙方當事人向戶政機關為離婚登記時消滅','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-039','114-3301',39,'single_choice','甲女之胎兒丙，在丙出生前，即由甲及丙之生父乙代丙與丁訂立收養契約，作為丁之養子女。嗣後， 戊醫師在甲懷孕丙期間為甲輸血，因戊之過失致甲感染病毒，並傳染於丙，而侵害丙之身體健康。下 列敘述，何者正確？','丙與丁之收養契約有效；在丙出生前，丙即得向戊請求損害賠償','丙與丁收養契約得撤銷；須於丙完全出生（非死產）時，丙始得向戊請求損害賠償','丙與丁收養契約無效；在丙出生前，丙即得向戊請求損害賠償','丙與丁之收養契約效力未定；須於丙完全出生（非死產）時，丙始得向戊請求損害賠償','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-040','114-3301',40,'single_choice','依民法規定，下列何者不得向法院聲請宣告變更為父姓或母姓？','父母一方生死不明未滿三年者','父母雙方死亡者','父母離婚但約定共同行使權利者','父母一方遺棄子女多年者','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-041','114-3301',41,'single_choice','甲女單身收養乙男，經過5 年，甲女與丙男結婚。乙男成年後，與丁女結婚。又經過多年，甲女死亡， 法院許可乙男聲請終止甲、乙之收養關係。若乙男死亡，丁女與丙男結婚時，其效力如何？','有效','無效','效力未定','得撤銷','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-042','114-3301',42,'single_choice','關於遺產酌給之請求及遺產管理，下列敘述，何者錯誤？','遺產分割之費用，由遺產中支付之','遺產管理人應編製遺產清冊及為保存遺產必要之處置','被繼承人生前繼續扶養之人，應由遺產管理人決定酌給遺產','遺產管理人得請求報酬，由遺產中支付之','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-043','114-3301',43,'single_choice','甲男乙女為夫妻，有一未成年子丙。甲受監護宣告，法院指定甲之父戊為甲之監護人。乙立遺囑指定 丁為丙之監護人。乙死亡後，下列何者為丙之監護人？','甲','丁','戊','社會福利機構','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-044','114-3301',44,'single_choice','下列關於遺囑能力之敘述，何者正確？','無意識或精神錯亂中所為之遺囑，得於回復常態後撤銷之','無行為能力人不得自為遺囑，須由其法定代理人代為之','滿16 歲之限制行為能力人所為之遺囑，爾後不論成年與否，均得依遺囑方式撤回','未滿16 歲之限制行為能力人，須得法定代理人允許，所為之遺囑方為有效','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-3301-045','114-3301',45,'single_choice','繼承人未開具遺產清冊時，關於清償被繼承人之債務，下列敘述，何者錯誤？','繼承人對於被繼承人債權人之無擔保債權，仍應按其數額，比例計算，以遺產分別償還','繼承人在違法清償後，得對不當受領之債權人，請求返還其不當受領之數額','繼承人按其行為能力，於違法清償被繼承人之債務時，異其責任','債權人得向法院聲請命繼承人於三個月內提出遺產清冊','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-046','114-3301',46,'single_choice','單親父親甲有子女乙、丙、丁、戊四人，其中乙育有一女己，丙育有一女庚，丁育有一子辛，戊育有 一子壬。甲死亡時，下列關於代位繼承之敘述，何者錯誤？','若乙與甲飛機失事同時死亡，己得代位繼承乙之應繼分','若丙於甲生前故意殺丁未遂但被判刑確定者，甲死亡時，由庚代位繼承丙之應繼分','若丁於甲死後首先發現其遺囑，但立即將其燒燬湮滅時，由辛代位繼承丁之應繼分','若戊於甲死後，依法辦理拋棄繼承時，由壬代位繼承戊之應繼分','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-047','114-3301',47,'single_choice','下列何種紛爭，當事人無法請求法院定之？','繼承人就遺產之管理方法，既無法達成協議，亦無法達成民法第828 條第2 項準用第820 條第1 項 有關共有物管理規定之決定','夫妻離婚時，就未成年子女權利義務之行使或負擔，無法協議達成由一方或雙方共同任之','扶養義務人與扶養權利人，就扶養費之金額，無法達成協議','繼承人與遺囑執行人，就遺囑執行之報酬，無法達成協議','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-048','114-3301',48,'single_choice','被繼承人甲有妻乙、子丙、孫丁與母戊，下列何者非屬民法第1145 條所謂故意致應繼承人於死之 情形？','乙殺害丙','丁殺害戊','丙殺害乙','丁殺害丙','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-049','114-3301',49,'single_choice','甲有一子乙已成年。甲生前對丙、丁各負有債務新臺幣（下同）100 萬元。甲死亡時，僅有遺產100 萬元。乙未開具遺產清冊陳報法院，因此僅知甲對丙負有債務，對丁之部分，則毫無所知。乙將甲之 遺產全部對丙清償。下列敘述，何者正確？','乙依法負有限責任，對丁之部分，無須償還','乙得對丙請求返還50 萬元','乙應以自己之財產，對丁償還100 萬元','乙應以自己之財產，對丁償還50 萬元','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-050','114-3301',50,'single_choice','甲、乙為夫妻，甲死亡時，乙與甲之兄妹丙、丁二人共同繼承。乙分得市價新臺幣（下同）600 萬元 之房屋。丙、丁各分得300 萬元之古董、土地。丙分得之古董有瑕疵，經重新鑑價結果，僅價值180 萬元。丙向乙、丁請求損害賠償時，丁已無支付能力，不能償還其分擔額。乙應分擔多少金額之損害？','80 萬元','75 萬元','60 萬元','90 萬元','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-051','114-3301',51,'single_choice','關於民事訴訟上之訴訟權保障，下列敘述，何者正確？','基於有權利即有救濟之憲法原則，非因犯罪而受損害之人，於刑事訴訟程序附帶提起民事訴訟者， 如經刑事庭移送至民事庭，應許原告補繳裁判費，以補正起訴程式之欠缺','為保障當事人之聽審請求權，交付法庭錄音光碟之聲請，縱已逾越法定期限，亦應准許之','當事人因重大過失，逾時始行提出攻擊或防禦方法，有礙訴訟之終結者，法院仍應許其提出，以保 障聽審請求權','基於當事人訴訟權之保障，上訴人有律師為訴訟代理人者，如未依規定預納上訴審之裁判費，法院 亦應給予補正之機會，不得逕認上訴不合法','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-052','114-3301',52,'single_choice','下列何種情形，受訴法院有管轄權？','甲住臺南市，乙住臺中市，甲、乙共有坐落臺南市之A 地，甲向乙住所所在之臺灣臺中地方法院起 訴，請求分割A 地','甲住新竹市，乙住新竹縣，甲所有坐落苗栗縣之A 建物遭乙無權占有，甲向臺灣新竹地方法院（下 稱新竹地院）提起所有物返還訴訟，請求乙騰空返還A 建物，乙已到庭應訴為本案之言詞辯論','甲住新竹市，乙住桃園市，甲向乙購買坐落桃園市之A 地，雙方簽訂不動產買賣契約書之書面，契 約書載有如因該買賣契約爭議而涉訟，以新竹地院為第一審管轄法院，嗣乙拒絕履行該買賣契約， 甲向新竹地院起訴請求乙履行契約移轉A 地','甲住新竹市，乙住新竹縣，甲所有坐落苗栗縣之A 地遭人冒名設定抵押權予乙，甲乃以該抵押權不 存在為由，向新竹地院起訴，請求乙塗銷該抵押權登記','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-3301-053','114-3301',53,'single_choice','甲列乙為被告向行政法院起訴，經行政法院移送到民事法院，民事法院認為無審判權，下列敘述，何 者錯誤？','原則上民事法院應裁定停止訴訟程序，請求最高法院指定有審判權之管轄法院','甲、乙均具狀或記明筆錄表示合意由民事法院裁判，則民事法院不得裁定停止訴訟程序','於指定有審判權之管轄法院前，甲和乙應有陳述意見之機會','民事法院就行政法院移送之訴訟為裁判，上級法院仍可以無審判權為由廢棄裁判','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-054','114-3301',54,'single_choice','未成年人甲1、甲2 共同毆打乙致傷，乙乃列甲1 之法定代理人丙1、甲2 之法定代理人丙2 為共同 被告，均依民法第187 條第1 項規定起訴請求賠償。下列敘述，何者錯誤？','第一審法院判決乙全部勝訴者，如僅丙1 提起上訴，有關丙2 部分之判決即先行確定','丙1 為時效完成得拒絕給付之抗辯者，縱丙2 未援用該抗辯，法院仍得據以駁回乙所提全部之訴','乙得僅與丙2 成立訴訟上和解，並續行對於丙1 部分之訴訟','乙主張其受有肢體傷害之事實經丙1 自認者，如丙2 並未自認，有關丙2 部分之訴訟，法院不受丙 1 之自認所拘束','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-055','114-3301',55,'single_choice','甲為投資客，向乙買受A 屋後又轉賣予丙，丙嗣後主張A 屋有漏水情事，起訴請求甲減少價金。甲 表示其持有A 屋時間不到1 個月，對A 屋實際上狀況不清楚，應該是乙比較清楚實際上屋況，遂請 求法院對乙為訴訟告知。下列敘述，何者正確？','甲於言詞辯論期日得以言詞為訴訟告知之表示，並由書記官記明筆錄，再將筆錄送達予乙即可','訴訟告知之目的在使受告知人得準備為訴訟行為，故如甲提出告知書狀時，非由甲逕自送達乙，而 應由法院將書狀送達給乙及丙','乙受訴訟告知後，因有利害關係，故必須參加訴訟，但對於參加於甲或丙之訴訟，有其自由','告知訴訟後，為確保乙權益，法院應於乙參加前裁定停止訴訟程序','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-056','114-3301',56,'single_choice','同日在A 公司經營之樂園遊玩，因設備故障受有損害之甲、乙、丙等共30 人，擬起訴向A 公司請求 損害賠償。關於選定當事人制度，下列敘述，何者錯誤？','甲、乙、丙等共30 人得在30 人中選定甲1 個人或同時選定甲、乙、丙，為30 人全體起訴','訴訟繫屬後，甲、乙、丙等共30 人選定甲1 個人為被選定人，則其他29 人脫離訴訟','選定乙為被選定人及其更換、增減，均應以文書證之','選定人不得在文書上載明或以書狀提出於法院限制被選定人丙捨棄、認諾、撤回、和解之權限','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-057','114-3301',57,'single_choice','關於訴訟標的價額之計算，下列敘述，何者錯誤？','因撤銷詐害債權涉訟，以債權人主張之債權額為準；但被撤銷法律行為標的之價額低於債權人所主 張之債權額時，以該被撤銷之標的價額為準','債權人代位債務人向第三人提起訴訟者，以債務人與第三人間之權利義務關係為準','因分割遺產涉訟，以全部遺產於起訴時之總價值為準','訴訟標的之價額不能核定者，以民事訴訟法所定不得上訴第三審之最高利益額數加十分之一定之','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-058','114-3301',58,'single_choice','關於民事訴訟上法院命合併或分別辯論之職權，下列敘述，何者錯誤？','甲、乙分別對丙提起之訴訟，經法院命合併辯論者，應依共同訴訟之規定辦理之','經合併辯論之數宗訴訟，其當事人俱不相同或僅有一造相同者，法院不得合併裁判','甲合併對乙、丙提起之訴訟，其訴訟標的對於乙、丙必須合一確定者，法院不得命分別辯論','甲對乙提起預備合併之訴，其先、備位之訴不能同時併存者，法院不得命分別辯論','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-059','114-3301',59,'single_choice','當事人經合法送達，關於其無正當理由而未於期日到場之效力，下列敘述，何者錯誤？','言詞辯論期日原告到場、被告未到場時，原告得聲請一造辯論判決','言詞辯論期日原告未到場、被告到場時，如被告拒絕辯論，則視為合意停止訴訟程序','言詞辯論期日，兩造均未到場時，除別有規定外，視為合意停止訴訟程序','言詞辯論期日原告未到場時，被告不能聲請一造辯論判決，僅能由法院依職權判定是否宜一造辯論 而為判決','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-3301-060','114-3301',60,'single_choice','關於民事訴訟上之突襲性裁判，下列敘述，何者錯誤？','原告於言詞辯論期日當庭追加某請求權基礎，此前被告就該請求權基礎未有主張聲明或陳述之機會 者，如法院逕諭知辯論終結，並依該請求權基礎判決原告勝訴，應屬突襲性裁判','當事人主張之事實，究竟該當於發生何項法律關係，乃屬法官依職權所為之法律適用問題，不受當 事人主張或陳述之拘束，是法院所認當事人間之法律關係，與當事人所陳述或表明者，縱有不同， 逕採為判決之基礎，亦無突襲性裁判可言','當事人所未提出之事實，係法院於審理過程中知悉其存在者，如法院遽行以之為判決之基礎，即生 突襲性裁判','原告已陳明僅主張甲請求權基礎，沒有要主張乙請求權基礎者，如法院認甲請求權基礎不存在，即 行判決原告敗訴，尚非突襲性裁判','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('114-3301-061','114-3301',61,'single_choice','甲機關起訴主張乙於任職期間，借用A 宿舍，現乙已退休，使用借貸之目的完畢，請求乙返還A 宿 舍。乙則抗辯使用借貸之目的尚未完畢，如法院認其仍應返還宿舍，因其每月之退休金僅新臺幣（下 同）2 萬元，生活困難，聲請法院酌給適當履行期間，利其謀得棲身之所。第一審法院審理結果，認 為乙應返還A 宿舍予甲，並定履行期間。關於履行期間部分，下列敘述，何者錯誤？','就應否給予履行期間，法院應令甲、乙進行辯論','訴訟中經甲同意，法院得給予乙1 年之履行期間','甲、乙未能達成合意，第一審法院審理後發現乙確實生活困難，孤身一人，並無親友，得酌定給予 2 年之履行期間','第一審於民國111 年3 月13 日宣示判決乙應返還宿舍，但履行期間2 年。甲得提供150 萬元為乙 擔保後得假執行。該判決於111 年3 月16 日送達乙，於同年4 月30 日確定。甲未供擔保聲請假執 行，乙之履行期間應自判決確定之日起算','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('114-3301-062','114-3301',62,'single_choice','原告甲列乙為被告，向該管法院起訴，訴之聲明為：乙應給付甲新臺幣（下同）200 萬元。其事實主 張略以：乙於民國110 年1 月10 日向甲購買貨品一批，價金為200 萬元，乙為支付該價金，乃簽發 同額支票交付予甲，經提示後竟遭退票，爰依票據關係，求為判決如訴之聲明等語。經受訴法院向甲 闡明，依其聲明及事實上之陳述，尚得主張買賣價金給付請求權。下列敘述，何者正確？','經闡明後，不問甲有無表明要主張價金給付請求權，依法官知法原則，應就甲之票款給付請求權及 買賣價金給付請求權是否有理由均逐一為本案審理，並為本案判決','經闡明後，如甲表明要合併主張依買賣關係請求乙給付價金時，甲不得請求依選擇合併之方式為本 案審理','經闡明後，甲表明在本件訴訟亦要一併主張依買賣關係請求時，則受訴法院應適用通常訴訟程序為 本案審判','經闡明後，甲表明在本件訴訟亦要一併主張依買賣關係請求，而乙抗辯甲之票款請求已經罹於消滅 時效時，甲不得請求受訴法院先就價金債權存否為本案審判','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('114-3301-063','114-3301',63,'single_choice','原告甲列乙為被告，向管轄法院起訴請求判決命乙給付新臺幣（下同）200 萬元，主張：丙於某日向 甲借用200 萬元，由乙為其保證人，未依約定期限償還借款，為此提起本訴訟等語。對此，乙聲明求 為判決駁回甲之請求，辯稱：丙對甲不負有借款債務，所以乙無須負保證責任云云。下列敘述，何者 錯誤？','丙經法院許可後，得參加本訴訟之和解','丙於參加本訴訟之和解後，得與甲、乙一同提出書狀向本訴訟之受訴法院表明在甲請求金額之150 萬元以內，三人均願意照法院所定方案來解決紛爭','在本訴訟之和解程序上，甲與丙同意由丙償還系爭借款200 萬元經記明和解筆錄後，甲得據此為執 行名義','法院將和解方案送達於聲請定和解方案之丙時，視為和解成立，與確定判決有同一之效力，此後在 甲訴請丙償還系爭借款債務（主債務）之後訴訟，該2 人均不得再爭執該主債務存否','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('114-3301-064','114-3301',64,'single_choice','關於判決基礎資料之蒐集，得否將當事人本人作為證據方法加以調查，下列敘述，何者錯誤？','在受訴法院認為當事人本人所親身經歷之事實可資以推定應證事實存否時，法院得命該當事人本人 到庭為陳述，無須先經他造當事人之同意','法院為了蒐集證據資料以形成心證認為有需通知某一造當事人本人在言詞辯論期日到庭陳述時，如 該本人不從法院之命而無正當理由不到場，法院於必要時，尚得命將該本人拘提到庭','受訴法院認為當事人本人所親身經歷之事實可資以推定應證事實存否，乃命該本人到庭，此時如受 訊問事項涉及其職務上或業務上應遵守秘密義務者，該本人得拒絕陳述','法院為了蒐集證據資料以形成心證認為有需通知某一造當事人本人在言詞辯論期日到庭陳述時，如 該本人到庭而拒不陳述，經法院闡明後亦不說明具體之理由，則法院得予以審酌並依自由心證認定 應證事實之存否','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('114-3301-065','114-3301',65,'single_choice','下列何者，不符合民事訴訟法規定之證據調查方法？','囑託臺灣證券交易所調查被告在集中交易市場之證券交易明細','囑託他法院詢問住在當地之證人','前往法院轄區外勘驗房屋狀態、利用狀況，並囑託內政部國土測繪中心測量該房屋坐落位置及面積','囑託臺北市結構工程工業技師公會鑑定房屋結構安全，並命該公會指派之主辦鑑定技師在結文具結 後，作成鑑定報告送交法院','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('114-3301-066','114-3301',66,'single_choice','關於法院進行之調解，下列敘述，何者錯誤？','當事人成立之調解，與確定判決具有相同之效力','移付調解限於第一審程序，第二審程序不得為之','起訴前之調解成立後，當事人得提起宣告調解無效或撤銷調解之訴','當事人合意起訴前應先行調解者，一方逕行起訴，經他方為本案之言詞辯論後，不得再抗辯調解先行','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('114-3301-067','114-3301',67,'single_choice','關於簡易訴訟程序與通常訴訟程序之轉換，下列敘述，何者錯誤？','甲訴請乙返還借款新臺幣（下同）40 萬元，嗣於訴訟中擴張為60 萬元，除甲、乙合意繼續適用簡 易訴訟程序外，應由簡易庭法官裁定改用通常訴訟程序並繼續審理','甲訴請乙返還借款40 萬元，嗣於訴訟中擴張為60 萬元，如乙逕為本案言詞辯論，應視為已有適用 簡易訴訟程序之合意，並繼續適用簡易訴訟程序審理','甲訴請乙返還借款60 萬元，嗣於訴訟中減縮為40 萬元，應由普通庭法官裁定改用簡易訴訟程序並 繼續審理','甲訴請乙返還借款60 萬元，嗣於訴訟中減縮為40 萬元，然法院仍繼續適用通常訴訟程序審理並判 決，經乙向高等法院提起上訴，高等法院應適用通常訴訟事件第二審程序審理','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('114-3301-068','114-3301',68,'single_choice','關於小額訴訟之審理程序，下列敘述，何者錯誤？','法院認為適用小額程序不適當，得依職權以裁定改用簡易程序，並由原法官繼續審理','當事人均不得為適用小額程序而為一部請求','調查證據所需時間、費用與當事人請求顯不相當時，法院得不調查證據，審酌一切情況，認定事實， 為公平之裁判','當事人為訴之變更、追加或提起反訴，致請求給付超過新臺幣10 萬元，除兩造合意繼續適用小額 程序並經法院認為適當外，不得為之','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('114-3301-069','114-3301',69,'single_choice','甲以其他全部共有人乙、丙、丁為被告，起訴請求分割共有土地，經一審法院判決後，乙對一審判決 聲明不服，合法提起上訴。下列敘述，何者正確？','若丙、丁對一審判決並未聲明不服，乙上訴效力即不及於丙、丁2 人','乙於二審法院審理中，向法院具狀撤回上訴，無待通知其他當事人，即生撤回上訴之效力','丙於二審法院審理中，將其應有部分移轉予戊，法院應依聲請或依職權命戊承受訴訟','訴外人己主張丁之應有部分實為其借名登記，己已取得確定判決命丁返還該借名登記之應有部分， 惟尚未依確定判決辦理登記，己可聲請參加訴訟','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('114-3301-070','114-3301',70,'single_choice','甲主張乙侵害其名譽權，依民法第184 條第1 項前段、第195 條第1 項規定，起訴請求乙賠償非財產 上損害新臺幣180 萬元。經第一審法院判決甲全部敗訴，甲提起第二審上訴，仍遭第二審法院駁回上 訴。下列敘述，何者正確？','甲所委任之律師，以第二審判決有不備理由之違法，提起第三審上訴，不必於上訴理由狀中具體敘 述為從事法之續造，確保裁判之一致性或其他所涉及之法律見解具有原則上重要性之理由','甲就第二審判決，委任律師提起第三審上訴，不論上訴理由為何，均毋庸經第三審法院許可','甲委任律師為訴訟代理人提起第三審上訴，如被上訴人乙未委任律師為訴訟代理人，法院應速命其 補正','甲不得提起第三審上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('114-3301-071','114-3301',71,'single_choice','原告甲起訴請求判決命被告乙返還借款新臺幣（下同）900 萬元，主張：乙向甲借款900 萬元，於民 國113 年6 月6 日簽發面額1,000 萬元、到期日為同年10 月6 日之本票一紙交予甲作為清償方法， 屆期經提示未獲兌現，為此請求乙返還借款等語。第一審經本案審理後判決駁回原告之訴，甲上訴後， 第二審改判命乙償還借款1,000 萬元，乙上訴於第三審。下列敘述，何者正確？','第二審法院為訴外裁判，屬違背法令，第三審法院應將第二審判決廢棄，全部發回更審','第三審法院發回更審時，指出乙有無向甲借款900 萬元之事實尚待查明，第二審更審法院須受該發 回意旨之拘束，僅得調查該事實','第二審判決命乙給付超過甲請求金額100 萬元之部分，既為訴外裁判，當然無效，乙不須上訴，第 三審法院亦不須將該部分廢棄','乙在事實審始終否認借款之事實，第二審法院僅以乙有簽發本票之事實為憑，別無其他佐證，即認 定兩造間因訂立消費借貸契約而有借貸關係，第三審法院得以第二審法院之事實認定違背經驗法則 及證據法則為由，廢棄原判決','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('114-3301-072','114-3301',72,'single_choice','關於簡易訴訟程序之第二審判決提起第三審上訴者，下列敘述，何者錯誤？','當事人於判決送達後提起第三審上訴，但未同時表明上訴理由者，法院應命其補正之','當事人提起第三審上訴，惟該事件所涉之法律見解如不具有原則上重要性者，原法院應駁回其上訴','若其上訴利益額已逾上訴第三審之上訴利益額者，當事人應以其適用法規顯有錯誤為理由，向最高 法院提起上訴','當事人提起第三審上訴時，應經原裁判法院之許可','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('114-3301-073','114-3301',73,'single_choice','甲向臺灣臺北地方法院（下稱臺北地院）起訴請求判命乙應返還借款新臺幣100 萬元及其法定遲延利 息，法院適用通常訴訟程序審理之結果，認為甲之請求無理由，乃判決駁回原告甲之訴，甲對該判決 不服提起上訴。關於第二審上訴，下列敘述，何者正確？','甲所提上訴，其管轄法院仍為臺北地院，並非臺灣高等法院，惟臺北地院之第二審審判須以合議為 之，不得由獨任法官審判','甲逾法定上訴期間所為之上訴，臺北地院不得以上訴不合法為由裁定駁回上訴','甲未於上訴狀內表明上訴理由，為上訴不合法，臺北地院應定期命提出，如逾期未補正者，第二審 法院應以裁定駁回上訴','甲上訴未繳納上訴裁判費，若臺北地院曾定期命其補正而未補正，第二審法院得不再命補正，逕予 裁定駁回上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('114-3301-074','114-3301',74,'single_choice','關於再審訴訟之裁判，下列敘述，何者錯誤？','再審原告提起再審之訴已逾30 日之不變期間者，法院應以再審之訴不合法，以裁定駁回之','法院認再審之訴合法，但無再審理由者，應以判決駁回再審之訴','法院認有再審理由者，應為開始再審之裁定，待裁定確定後，始依其審級之程序更為本案審理','法院認再審之訴雖有再審理由，但原確定判決為正當者，仍應以判決駁回再審之訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('114-3301-075','114-3301',75,'single_choice','甲持有付款人為乙銀行之系爭支票1 張，因故不慎遺失，經辦理票據掛失止付後，擬向法院聲請公示 催告及除權判決。下列敘述，何者錯誤？','法院依書面審理，審查聲請人所提出之事證，如認符合法律規定，即得以除權判決宣告系爭支票無效','甲得於公示催告裁定所定申報權利之期間已滿後3 個月內，聲請除權判決','甲具狀向法院聲請公示催告後，法院應就該聲請為裁定；法院准許聲請者，應為公示催告','應由證券所載履行地之法院，即付款人乙銀行所在地之法院管轄','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-3301-076','114-3301',76,'single_choice','甲列乙為被告，提起給付新臺幣200 萬元之訴訟，第一審法院准許甲之假扣押聲請，乙不服提起抗告。 關於抗告法院所為之裁定及後續之程序，下列敘述，何者錯誤？','抗告法院認乙之抗告有理由，廢棄原裁定而自為裁定，若非適用法規顯有錯誤，甲不得再為抗告','抗告法院認乙之抗告無理由，而為駁回之裁定，若非適用法規顯有錯誤，乙不得再為抗告','無論抗告法院認乙之抗告有無理由而為裁定，抗告權人欲再為抗告而未委任律師為訴訟代理人者， 抗告不因此而不合法','抗告法院認乙之抗告不合法而駁回者，乙不得再為抗告，但得提出異議','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-3301-077','114-3301',77,'single_choice','甲男與前妻育有一子丙，後甲與乙女未婚生下一子丁，甲拒不認領丁，乙遂以甲為被告提起認領子女 之訴（下稱A 訴訟），並基於不當得利返還請求權合併請求甲返還乙過去支出之子女扶養費（下稱B 訴訟）。下列敘述，何者正確？','如乙於判決確定前死亡，丁得於知悉乙死亡時起10 日內聲明承受A 訴訟，B 訴訟則視為終結','如甲於判決確定前死亡，其繼承人丙得承受A 訴訟與B 訴訟','甲與乙得就A 訴訟與B 訴訟成立訴訟上和解','如甲就A 訴訟與B 訴訟之訴訟標的為認諾，為求訴訟經濟，法院應為甲敗訴之本案判決','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-3301-078','114-3301',78,'single_choice','關於家事非訟事件之定性，下列敘述，何者錯誤？','父母之一方，依民法第1090 條規定，請求法院宣告停止他方對於未成年子女之權利者，其事件為 家事非訟事件','養父母、養子女之一方，依民法第1081 條規定，請求法院宣告終止雙方之收養關係者，其事件為 家事非訟事件','子女之一之友人，依民法第179 條規定，請求其他子女返還其代墊該子女之父母日常生活費用者， 其事件為家事非訟事件','家庭暴力之受害人，依家庭暴力防治法相關規定，請求法院對於家庭暴力之加害人核發通常保護令 者，其事件為家事非訟事件','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-3301-079','114-3301',79,'single_choice','關於家事身分訴訟事件之審理原則，下列敘述，何者正確？','應限制處分權主義，是離婚訴訟之當事人不得為訴訟上和解','應限制辯論主義，是撤銷婚姻訴訟之當事人，就構成撤銷婚姻之原因事實為自認者，不生效力','應限制公開主義，是確認親子關係存在之訴，縱經法律上利害關係人聲請，其處理程序亦不許旁聽','應限制言詞主義，是認領之訴，其判決得不經言詞辯論為之','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-3301-080','114-3301',80,'single_choice','甲之繼承人為其妻乙及子丙、丁，丁起訴請求依甲之遺囑分割遺產後，乙另對丙、丁起訴，請求分配 甲、乙間之夫妻剩餘財產。下列敘述，何者錯誤？','乙、丙、丁對於夫妻剩餘財產分配及分割遺產縱使達成合意，不可成立訴訟上和解，仍應由法院裁判','在分割遺產訴訟，若乙或丙認為丁提出之遺囑非屬真正，得反請求確認遺囑無效','丁提起分割遺產訴訟，應以乙、丙為共同被告','法院得將乙提起之夫妻剩餘財產分配訴訟，移送由分割遺產訴訟法院合併審理','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-4301-001','114-4301',1,'single_choice','非公開發行且非閉鎖性之A 股份有限公司，不得於章程中明訂發行下列何種之特別股？','每股有10 個表決權之特別股','得當選一席董事之特別股','對經理人任免具否決權之特別股','附轉讓限制之特別股','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-4301-002','114-4301',2,'single_choice','A 有限公司（下稱A 公司）之股東為甲、乙、丙、丁及戊5 人，每位股東出資新臺幣（下同）50 萬 元，股東表決權係按出資比例分配。A 公司擬增資100 萬元，甲、乙及丙表示贊成，丁及戊反對。依 公司法之規定，下列敘述何者正確？','甲贊成本件增資案，故有按出資比例進行增資之義務','丙贊成本件增資案，但不負出資義務','乙贊成本件增資案，但因資金短缺，得自行邀請第三人辛出資而成為新股東','丁反對本件增資案，但得將其分配到之增資額度，自行邀請第三人庚出資而成為新股東','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-4301-003','114-4301',3,'single_choice','下列有關公司名稱之敘述，何者正確？','公司不得使用與其他公司相同之名稱，但若該公司業經廢止登記，自廢止登記之日起，逾10 年未 清算完結者，原則上該公司名稱仍得申請核准使用','公司名稱被法院判決確定不得使用，公司於判決確定後6 個月內未辦妥名稱變更登記者，主管機關 應即命令公司解散','公司名稱不得使用易於使人誤認其與公益團體有關之名稱，除非獲得該公益團體之同意，則可不受 限制','兩公司之特取名稱雖相同，但只要公司名稱中有標明不同公司種類，則視為不相同','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-4301-004','114-4301',4,'single_choice','股票未公開發行之A 公司（下稱A 公司）為B 上櫃公司（下稱B 公司）之原料供應商，某次A 公司 增資發行新股時，就原有股東未認購之部分，洽B 公司認購，B 公司章程並未有轉投資之相關規定。 依公司法之規定，下列敘述何者正確？','A 公司股票未公開發行，無論B 公司認購A 公司股份之金額多寡，僅須董事會決議即得為之','B 公司章程並未有轉投資之相關規定，故B 公司認購A 公司股份之金額並無限制','B 公司認購A 公司股份之金額如超過B 公司實收股本之40%，則須經過B 公司股東會特別決議始 得為之','A 公司股票未公開發行，B 公司不得認購A 公司股份','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-4301-005','114-4301',5,'single_choice','甲為已成年之自然人，擬設立一家公司。依公司法規定，下列敘述何者錯誤？','如甲選擇設立有限公司，得以勞務作為出資方式','如甲選擇設立股份有限公司，須再找一名股東始得設立','如甲選擇設立有限公司，甲一人即可設立','如甲選擇設立股份有限公司，得以技術作為出資方式','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true)
insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('114-4301-006','114-4301',6,'single_choice','A 股份有限公司（下稱A 公司）持有B 股份有限公司（下稱B 公司）已發行有表決權股份總數5%之 股權，但A 公司對B 公司之人事、財務與業務具有實質掌控力。民國110 年1 月至12 月，B 公司向 A 公司採購產品，惟A 公司索取之對價為超乎市場價格之不當高價，造成B 公司蒙受新臺幣（下同） 1,000 萬元之損失，下列敘述何者錯誤？','A 公司及其董事對B 公司之1,000 萬元損害負連帶賠償責任','若B 公司對A 公司本有1,000 萬元之債權，A 公司不得主張以其對B 公司所有之上述1,000 萬元貨 款債權抵銷之','A 公司對B 公司因上述交易而產生之1,000 萬元貨款債權，在B 公司破產時，不得優先於其他債 權人受償，其受償次序與一般債權人同','A 公司與B 公司間之交易若使B 公司受有損害，繼續1 年以上持有B 公司已發行有表決權股份總 數1%以上之股東，得以自己名義，請求A 公司向B 公司為損害賠償','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-4301-007','114-4301',7,'single_choice','公司法中關於有限公司之規定，下列敘述何者正確？','有限公司之清算，準用無限公司相關規定','有限公司變更章程，應經股東表決權四分之三以上之同意','有限公司解散時，應有全體股東之同意','有限公司合併時，應經股東表決權過半數之同意','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-008','114-4301',8,'single_choice','A 股份有限公司（下稱A 公司）為非公開發行股票公司，因業務擴展，有擴建廠房及擴充設備需求， 有意向大眾投資人募資。依公司法規定，有關公司對外公開發行股票之規定，下列敘述何者錯誤？','A 公司對外募集股份，仍需保留發行新股總數百分之十至十五之股份由公司員工承購','A 公司有資產不足抵償債務之情形，惟依其事業性質，須有較長準備期間或具有健全之營業計畫， 確能改善營利能力者，仍得對外公開發行','A 公司公開發行新股時，應以現金為股款','A 公司若最近3 年皆為虧損，不得公開發行具有優先權利之特別股','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-009','114-4301',9,'single_choice','A 上市公司（下稱A 公司）因財務困難，由最大債權人B 銀行向法院聲請重整，經法院審理後裁定 開始重整，依法律規定及實務見解，下列關於法院所為重整裁定之敘述，何者正確？','法院不得選派A 公司之董事擔任重整人','B 銀行雖為法人組織，法院仍得選派B 銀行為重整人','關係人會議分組行使表決權之結果，有任何一組主張另行選定重整人時，得提出候選人名單，聲請 法院選派之','法院為重整裁定時，應選任A 公司之獨立董事或獨立監察人為重整監督人','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-010','114-4301',10,'single_choice','公司法於民國104 年7 月引進閉鎖性股份有限公司制度，關於此制，下列敘述何者錯誤？','閉鎖性股份有限公司專節增訂後，公司法第2 條規定之公司種類增加為5 種','閉鎖性股份有限公司必為非公開發行股票公司','閉鎖性股份有限公司雖不得公開發行或募集有價證券，但得經由證券商經營股權群眾募資平臺募資','閉鎖性股份有限公司之股東人數上限，中央主管機關得視社會經濟情況及實際需要增加之','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-011','114-4301',11,'single_choice','A 有限公司（下稱A 公司）資本額新臺幣（下同）300 萬元，經營績效良好，歷年提撥之法定盈餘公 積已達300 萬元，有甲、乙及丙等3 位股東各出資100 萬元，由甲擔任董事，章程並訂明以當年度獲 利狀況之10%，分派員工酬勞。關於其今年財務及會計處理之敘述，下列何者正確？','A 公司於彌補虧損完納一切稅捐後，分派盈餘時，應先提出10%為法定盈餘公積','每屆會計年度終了，董事甲應依法造具各項表冊，分送各股東，請其承認；其承認應經股東表決權 三分之二之同意','A 公司得以章程訂定，或經股東表決權三分之二以上之同意，另提特別盈餘公積','董事甲得決定員工酬勞以股票為之，並向乙及丙報告','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-012','114-4301',12,'single_choice','A 股份有限公司（下稱A 公司）進行下列何事項時，須變更公司章程？','A 公司章程規定：「本公司資本總額定為新臺幣5,000 萬元，分為500 萬股。每股金額新臺幣10 元。」若A 公司已發行股份為300 萬股，A 公司為改善財務結構，減資100 萬股彌補虧損，再增資 100 萬股，引進新資金','A 公司已發行之甲種特別股享有兩倍股息及紅利之權利，A 公司近年獲利情況不佳，欲縮減甲種 特別股股東股息與紅利','A 公司因公開發行成本過高，申請停止公開發行','A 公司之股東會為解散之決議','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-013','114-4301',13,'single_choice','A 股份有限公司為非公開發行股票公司，若將公司之盈餘分派從年度分派，改為每季分派，下列敘述 何者正確？','公司做每季分派不需章程規定，惟須經董事會特別決議後始得為之','若要進行分派，公司當季需有獲利，惟公司累積虧損得待會計年度終了後，再進行彌補','第三季終了後分派盈餘，若發放股票股利，無須經股東會決議通過','第一季終了後分派盈餘，若發放現金股利，僅須經董事會決議通過','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-014','114-4301',14,'single_choice','A 有限公司（下稱A 公司）共有甲、乙、丙、丁及戊5 位股東，甲及乙擔任董事。依公司法相關規 定，下列敘述何者正確？','A 公司章程設置董事長之規定，應經股東表決權過半數之同意選任之','A 公司章程未設置董事長者，董事甲和乙均得代表公司','丙行使監察權時，得代表公司委託律師或會計師審核之，但應自行負擔費用','丁行使監察權時，得經法院許可，向董事甲和乙質詢公司營業情形，查閱財產文件、帳簿及表冊','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-4301-015','114-4301',15,'single_choice','A 股份有限公司（下稱A 公司）持有B 股份有限公司（下稱B 公司）已發行股份總數百分之六十， 並指派其代表人甲擔任B 公司董事。A 公司與B 公司擬合併，於B 公司董事會、股東會表決「與A 公司合併」議案時，甲、A 公司應否迴避表決？','甲、A 公司皆應迴避','僅甲應迴避','僅A 公司應迴避','甲、A 公司皆無須迴避','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-016','114-4301',16,'single_choice','有關保險業、銀行、保險經紀人及代理人可經營的業務範圍，下列何者錯誤？','財產保險業經營財產保險，人身保險業經營人身保險，同一保險業不得兼營財產保險及人身保險業 務。但財產保險業經主管機關核准經營傷害保險及健康保險者，不在此限','銀行經主管機關許可，可擇一兼營保險代理人或保險經紀人或保險公證人業務','經紀人公司得申請經營保險經紀業務、再保險經紀業務、或同時經營保險經紀業務及再保險經紀業 務；經紀人同時具備財產保險及人身保險經紀人資格者，得同時申領財產保險及人身保險經紀人執 業證照','代理人同時具備財產保險及人身保險代理人資格者，除經主管機關核准外，僅得擇一申領財產保險 或人身保險代理人執業證照','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-017','114-4301',17,'single_choice','甲以其所有作為營業用之A 房屋，向X 保險公司（下稱X 公司）投保商業火險，於保險期間，因所 營業務狀況不好，甲遂結束於A 屋之營業並將A 屋作為純住宅使用。依我國保險法之規定，下列敘 述何者正確？','甲應於結束A 屋之營業前10 日通知X 公司','甲只需於A 屋之營業結束後通知X 公司即可','X 公司得終止契約','甲得請求X 公司重新核定保險費','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-018','114-4301',18,'single_choice','甲向乙以附條件買賣方式租買新車乙部，甲分期支付租買價金，三年支付全部價金後，甲取得汽車所 有權。甲以自己為被保險人向A 保險公司投保汽車之甲式車損及竊盜險新臺幣300 萬元，並約定乙 為事故損失保險金受款人。租買及保險期間，汽車在甲返交乙進行定期保養時，乙違規駕駛致汽車全 損，乙向A 保險公司請求全額車損賠償，A 保險公司主張本件無保險利益，保單失其效力，試問有無 理由？','有理由，甲非汽車所有權人，無保險利益','無理由，甲為汽車之承租人，具保險利益','有理由，甲對汽車的保險利益應至清償所有分期租買款項取得汽車所有權時方具保險利益','無理由，乙為事故損失保險金受款人且為契約所有權人，具保險利益，因此保單有效','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-019','114-4301',19,'single_choice','甲以其配偶乙為被保險人，指定甲為受益人，投保死亡保險，並約定保險金額，經乙書面同意。數年 後，甲、乙離婚，乙於離婚後一年死亡，死亡前尚未撤回同意。下列敘述何者正確？','甲不得請求保險給付，因離婚後甲對乙已無保險利益，契約失其效力','甲不得請求保險給付，因離婚後甲喪失受益人資格','甲得請求保險給付，因契約訂立時甲為乙之配偶，且保險契約仍持續具效力','甲得請求保險給付，但因甲、乙已離婚，保險公司只須退還甲保險費','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-020','114-4301',20,'single_choice','為保障保戶及股東權益，保險法規定保險業自有資本與風險資本之比率及淨值比率，不得低於一定比 率，並劃分為數種資本等級。其中針對資本顯著不足的保險業，主管機關得令其降低對負責人、經理 人之報酬。其降低後之報酬不得超過該保險業資本等級列入資本顯著不足等級前十二個月內對該負責 人支給平均報酬之百分比為何？','百分之七十','百分之七十五','百分之八十','百分之九十','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-021','114-4301',21,'single_choice','關於人壽保險契約保險費到期未交付之催告、契約效力之停效與復效相關規定，下列敘述何者正確？','人壽保險之保險費到期未交付者，經催告到達後屆二十日仍不交付時，保險契約之效力停止','催告應送達於要保人，或負有交付保險費義務之人之最後住所或居所，保險費經催告後，應依與保 險人約定之交付方法交付之；保險人並應將前開催告通知被保險人以確保其權益。對被保險人之通 知，依最後留存於保險人之聯絡資料，限於以書面發出通知時，視為已完成','停止效力之保險契約，於停止效力之日起九個月內清償保險費、保險契約約定之利息及其他費用後， 翌日上午零時起，開始恢復其效力','保險契約所定申請恢復效力之期限，自停止效力之日起不得低於二年，並不得遲於保險期間之屆滿日','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('114-4301-022','114-4301',22,'single_choice','甲向A 保險公司（下稱A 公司）投保傷害保險新臺幣（下同）200 萬元，並以價值70 萬元之汽車向 B 保險公司（下稱B 公司）投保車體險並約定自負額5 萬元。某日因乙之駕車過失，導致甲失能、汽 車全毀。A 公司就失能部分依保險契約理賠100 萬元，B 公司就車損理賠65 萬元。設甲對於肇事原 因並無過失時，有關本案適用保險代位之情形，下列敘述何者正確？','A 公司與B 公司均不得行使代位權','A 公司不得行使代位權，B 公司得代位求償65 萬元','A 公司得代位求償100 萬元，B 公司得代位求償70 萬元','A 公司得代位求償100 萬元，B 公司得代位求償65 萬元','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-023','114-4301',23,'single_choice','甲以自己為被保險人向A 保險公司（下稱A 公司）投保傷害保險，並以乙為其死亡時之受益人。下 列敘述何者錯誤？','A 公司於甲遭受意外傷害及其所致失能或死亡時，負給付保險金之責','甲故意自殺，或因犯罪行為，所致傷害、失能或死亡，A 公司不負給付保險金之責','乙故意傷害甲未遂時，甲得撤銷其受益權利','乙故意傷害甲者，A 公司不負保險金給付之責','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-024','114-4301',24,'single_choice','甲於民國107 年（下同）5 月1 日以自己為被保險人，向A 保險公司（下稱A 公司）投保人壽保險， 約定死亡保險金額1,000 萬元，指定其妻乙為受益人。A 公司於5 月15 日以簡訊告知甲核保通過， 並告知其應繳交之保險費金額與繳交日期。然甲於次日赴A 公司交付保險費途中發生車禍，甲當場 死亡。乙請求保險金給付時，A 公司得否拒絕？','A 公司以簡訊告知已核保通過，保險契約即已成立，除另有以保險費之交付為要件者外，A 公司不 得拒絕乙之請求','甲尚未繳付保險費，保險契約未成立，A 公司得拒絕給付保險金','A 公司雖已核保通過，但尚未交付保險單，保險契約尚未成立，A 公司無須給付','甲與A 公司間保險契約雖已成立，但因甲尚未履行其給付對價之義務，故A 公司亦無須給付','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-025','114-4301',25,'single_choice','要保人暨被保險人甲向A 壽險公司（下稱A 公司）投保意外傷害死亡險新臺幣300 萬元，保單附約 約定「被保險人職業有變更，依本公司職業分類，其危險性增加者，應通知本公司，本公司於接到通 知後，自職業變更之日起，按差額比例增收未滿期保險費；未通知而發生保險事故者，本公司按其原 收保險費與應收保險費之比率折算保險金給付。」甲於要保時，要保書上的職業欄填無，投保後因疫 情及經濟問題開始從事膠筏漁業工作，未通知A 公司，漁業工作時發生落海事故死亡。保險人A 公 司下列主張，何者正確？','A 公司得依保險法第64 條規定，以被保險人違反最大誠信之理由，解除契約，無庸負責','A 公司得依保險法第59 條第2 項及第57 條規定，以怠於通知危險增加之理由，解除契約，無庸 負責','職業從「無」變更為「膠筏漁業工作」，無涉危險增加，保險人A 公司應全額負責','職業從「無」變更為「膠筏漁業工作」，涉危險增加，但未通知，保險人A 公司應依約負比例責任','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-026','114-4301',26,'single_choice','甲於某年3 月1 日簽發本票一紙予乙，到期日為同年3 月18 日，並免除作成拒絕證書。乙於同年3 月5 日背書轉讓予丙。丙至遲應於何日向甲提示請求付款，始符票據法之規定？','同年3 月18 日提示','同年3 月19 日提示','同年3 月20 日提示','同年3 月21 日提示','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-027','114-4301',27,'single_choice','甲為喜好放空股市之風險追求者，但因操作不力，資金套牢。其之前曾簽發發票日為民國109 年4 月 8 日之支票，但存款帳戶內資金僅能支應該支票面額1/5 之票款。為等待股市走向再度翻轉，甲商請 執票人晚些提示，執票人遂在提示期限經過後3 個月始提示。假設甲之資金仍舊套牢，依票據法之規 定，下列敘述何者錯誤？','銀行可予以付款','銀行可不予付款','甲得撤銷付款之委託','銀行不得僅支付1/5 之票款，必須先幫發票人墊付，再向發票人請求全額償還','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-028','114-4301',28,'single_choice','在肺炎疫情期間，口罩短缺，居住苗栗市之善心人士甲先生，發起由當地之社區發展協會以家庭代工 方式製作口罩套以協助政府防疫，遂向高雄市之原料廠商A 公司進貨一批，簽發支票一紙予A 公司， 發票地在苗栗市、付款地在高雄市。本紙支票之提示期限為何？','發票日後7 日內','發票日後14 日內','發票日後15 日內','發票日後2 個月內','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('114-4301-029','114-4301',29,'single_choice','A 公司於某年2 月14 日簽發匯票予B 公司，付款人為C 銀行，票上記載免除作成拒絕證書，到期日 記載為同年3 月14 日，B 公司至同年3 月15 日始向C 銀行提示付款。下列敘述何者正確？','B 公司之提示尚未逾法定期限','B 公司之提示已逾法定期限，但仍在發票日後6 個月內，故提示仍為有效','B 公司之提示已逾法定期限，惟若獲得C 銀行之同意，提示仍屬有效','此張匯票既已免除作成拒絕證書，則根本不必提示','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-030','114-4301',30,'single_choice','甲欲向丙借調現金，但丙擔心甲信用不足，甲與乙簽訂擔保契約請求乙擔任支票之背書人，並簽發無 記名支票一紙交由乙收執，再由乙在支票背面空白背書後交給甲，甲持由乙空白背書之支票向丙調借， 丙於是將相當於票款之現金交付給甲，經丙遵期提示後，不獲付款。下列敘述何者正確？','乙不必負背書責任，因為該支票背書不連續','乙不必負背書責任，因為該支票為發票人甲回頭背書之票據','乙應負背書責任，因為乙在支票背面背書','乙應負背書責任，因為甲、乙間訂有擔保契約','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-031','114-4301',31,'single_choice','甲日常習慣於皮夾中保存一張已完成簽名蓋章之支票，以應不時之需。某日，知甲有此習慣之乙遂偷 偷從甲皮夾中取走該票據，完成金額及所缺之應記載事項，並記載乙自己為受款人後，再將該票背書 轉讓予善意且給付合理對價之丙。甲於票據遭竊後，未進行任何票據遺失之救濟程序，丙持該票向銀 行請求付款遭拒後，得否向甲主張？','因甲未於該票上填載金額，該票欠缺應記載事項而無效，故甲不負票據責任','因丙為善意取得已具備票據法規定應記載事項之票據，甲不得主張該票據原欠缺應記載事項而拒絕 付款','因該票應記載事項係由乙完成填載，是以丙僅得向乙主張，而不得向甲主張','甲需證明該票原欠缺應記載事項，始得對抗善意之丙而拒絕付款','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-032','114-4301',32,'single_choice','甲簽發本票一紙交付予乙，乙於到期日前背書轉讓予丙，丙於到期日向甲提示付款遭拒後並依法作成 拒絕證書，下列關於丙行使權利之敘述，何者錯誤？','向甲追索時，丙得聲請法院裁定後強制執行','丙行使追索權時，甲與乙連帶對丙負責','向乙追索時，丙得直接聲請法院裁定後強制執行','丙行使追索權時，可直接先向甲追索','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-033','114-4301',33,'single_choice','甲於民國（下同）105 年1 月1 日簽發面額為新臺幣（下同）20 萬元之本票一紙與乙，以清償所欠款 項20 萬元，唯該本票上漏未記載到期日。乙隨後將該本票背書後無償讓與其友丙，賀其小店開張。 丙即以該本票償付積欠廠商丁之貨款。丁返家後將該本票置於抽屜後即忘記持票請求，於109 年整理 抽屜時始發現該本票而欲主張其權利。下列敘述何者正確？','該本票因未記載到期日，欠缺法定應記載事項而無效，丁無從主張其權利','丁得持該票向甲主張付款，甲為發票人，不得拒絕','乙係無償讓與該票，故乙不負任何票據責任，但丁仍可向丙請求','丁僅得向甲主張利益償還請求權','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-034','114-4301',34,'single_choice','乙執有甲簽發之匯票一紙，乙記名背書轉讓予丙，以支付貨款，乙於簽名旁加註：「若丙未交貨時， 此背書無效」。下列對該匯票之敘述，何者正確？','背書無效','匯票無效','乙於簽名旁之加註有效','乙無條件負背書責任','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-035','114-4301',35,'single_choice','A 公司為經營江浙菜館之業者，開立匯票予販售肉品之B 公司，購買一個月份之肉品，並由自己擔任 付款人，匯票到期日為民國109 年4 月6 日。惟民眾於此段期間內，為避免群聚而增加感染新冠肺炎 的風險，大多在家自炊，餐飲業者業績大受影響。A 公司也因此現金周轉不靈，於B 公司在到期日提 示時，A 公司希望延期付款，依票據法之規定，下列敘述何者正確？','須得B 公司之同意，無特定期限之限制','須得B 公司之同意，但以提示後2 日為限','須得B 公司之同意，但以提示後3 日為限','須得B 公司之同意，但以提示後4 日為限','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-036','114-4301',36,'single_choice','下列何者不是證券交易法所稱之發行人？','以公開招募方式出售持有A 股份有限公司股票之持股人甲','作為募集設立B 股份有限公司之發起人的自然人乙','作為募集設立C 股份有限公司之發起人的D 股份有限公司','辦理現金增資而募集發行股票之E 股份有限公司','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('114-4301-037','114-4301',37,'single_choice','A 上市公司（下稱A 公司）章程規定設有七席董事，該公司並設置審計委員會。其中，審計委員會之 成員由甲、乙、丙三人組成。依證券交易法之規定，下列敘述何者錯誤？','甲、乙、丙三人必須皆為獨立董事，且至少一人應具備會計或財務專長','審計委員會之決議，應有過半數成員之出席，出席成員過半數之同意行之','A 公司之年度財務報告如未經審計委員會決議通過，仍不得由全體董事三分之二以上同意行之','若甲、乙、丙三人均解任時，A 公司應自事實發生之日起60 日內，召開股東臨時會補選之','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-038','114-4301',38,'single_choice','A 股份有限公司（下稱A 公司）股票已公開發行，但尚未上市（櫃），A 公司如未能於本年6 月30 日 前召開股東常會，得否報請主管機關核准延期召開本年度股東常會？','A 公司僅須報請經濟部核准，即得延期召開股東常會','A 公司僅須報請金融監督管理委員會核准，即得延期召開股東常會','A 公司不得報請經濟部或金融監督管理委員會核准延期召開股東常會','A 公司如得經濟部及金融監督管理委員會核准，即得延期召開股東常會','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-039','114-4301',39,'single_choice','股票上市之A 公司實收資本額新臺幣10 億元，設7 席董事，近日公告買回其股份之內容如下列選項， 何者不符合證券交易法規定？','買回目的：配合附認股權公司債','預定買回股份占公司已發行股份總數之比率：1.5%','董事會決議買回股份之紀錄：4 席董事出席，經主席徵詢全體出席董事無異議通過','買回方式：自集中交易市場買回','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-040','114-4301',40,'single_choice','A 股份有限公司（下稱A 公司）為一家從事資訊服務的上市公司，該公司設有常務董事，則A 公司 常務董事中獨立董事人數不得少於幾人，且不得少於常務董事席次多少比例？','常務董事中獨立董事人數不得少於一人，且不得少於常務董事席次三分之一','常務董事中獨立董事人數不得少於二人，且不得少於常務董事席次五分之一','常務董事中獨立董事人數不得少於一人，且不得少於常務董事席次五分之一','常務董事中獨立董事人數不得少於二人，且不得少於常務董事席次三分之一','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-041','114-4301',41,'single_choice','A 上市公司（下稱A 公司）設有甲、乙、丙三名獨立董事，並由甲、乙、丙三人組成薪資報酬委員會。 關於薪資報酬委員會之敘述，下列何者正確？','依公司法規定，董事報酬為股東會決議事項，所以A 公司薪資報酬委員會不得就董事報酬加以討論','A 公司薪資報酬委員會應至少每年召開2 次','A 公司薪資報酬委員會所討論之經理人薪酬範圍，僅限於經理人之薪資，而不應包含經理人所享 有之股票選擇權','A 公司董事會討論薪資報酬委員會之建議時，若不採納薪資報酬委員會之建議，應由董事會全體 董事同意行之，並於決議中具體說明通過之薪資報酬有無優於薪資報酬委員會之建議','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-042','114-4301',42,'single_choice','公開收購條件成就後，應賣人於何時得不經催告而逕行解約？','隨時均可任意解約','公開收購人未於公開收購說明書記載之支付收購對價時間完成支付者','公開收購人縮短公開收購期間時','公開收購人調降公開收購價格時','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-043','114-4301',43,'single_choice','A 公司當選為B 上市公司（下稱B 公司）之法人董事，並指派代表人甲行使董事之職權，甲利用其 配偶之名義，於民國113 年7 月31 日買進B 公司普通股股票，A 公司於同年12 月18 日改派其代表 人為乙，甲復於同年12 月20 日賣出B 公司有表決權特別股股票，依目前主管機關之見解，B 公司不 得向甲行使短線交易歸入權之理由為何？','因法人董事之代表人甲並不受短線交易之規範','因買進B 公司股票之人為甲之配偶，賣出B 公司股票之人為甲，兩者無法行使歸入權','因甲於賣出B 公司之特別股時，已不具備法人董事代表人之身分','因買進之有價證券為B 公司普通股，賣出之有價證券為B 公司有表決權特別股','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-044','114-4301',44,'single_choice','下列關於我國現行證券集中保管制度之敘述，何者錯誤？','集中保管之有價證券係以帳簿劃撥方式辦理買賣交割','集中保管有價證券之設質交付，適用民法第九百零八條之規定','上市（櫃）公司發行股票應採帳簿劃撥交付之無實體發行','集中保管之股票係以證券集中保管事業之名義登載於股票發行公司股東名簿','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('114-4301-045','114-4301',45,'single_choice','A 上市公司（下稱A 公司）之產品以外銷為主，A 公司主要客戶於某年4 月1 日片面停止與A 公司 之全部業務往來，同年4 月2 日即有國外媒體加以報導，4 月3 日國內媒體亦陸續報導，當日股價即 大幅向下修正。A 公司迫於輿論壓力於4 月4 日清明節上午召開記者會說明，隨即於下午將系爭消息 輸入公開資訊觀測站。依主管機關規定之公開方式，系爭重大消息何時公開？','4 月2 日國外媒體開始報導時','4 月3 日國內媒體開始報導時','4 月4 日上午召開記者會說明時','4 月4 日下午將系爭消息輸入公開資訊觀測站時','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-046','114-4301',46,'single_choice','甲將其B 屋租給乙，約定2 年後乙須返還租賃物；乙每個月須支付租金新臺幣（下同）3 萬元，並約 定遲延給付租金達2 個月以上時，以上皆載明可逕為強制執行，另於租期屆滿後甲須返還乙押租金。 上述之事項均已經公證人作成公證書。下列敘述，何者正確？','就租賃物返還部分，於租期屆滿乙仍不返還，甲不得以此一公證書作為執行名義','租期屆滿甲未返還押租金，雖未記載可逕為強制執行時，乙仍得以此一公證書作為執行名義','乙積欠甲租金2 個月共6 萬元，甲得以此一公證書作為執行名義','乙不慎將B 屋中甲所有之C 衣櫃損毀，就此所生之損害賠償8 萬元，甲得以此一公證書作為執行 名義','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-047','114-4301',47,'single_choice','甲、乙共有土地一塊，甲之應有部分為三分之一，乙之應有部分三分之二。嗣甲以乙為被告，起訴請 求分割土地，經法院判決變價分割確定後，乙遂以該確定終局判決為執行名義，向執行法院聲請就土 地變價分割。執行法院應如何課徵執行費？','以土地全部價額核定之','以土地價額三分之二核定之','以土地價額三分之一核定之','以乙之應有部分預估價額命先暫繳，待拍定時再按拍定總額計徵執行費用','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-048','114-4301',48,'single_choice','甲以乙積欠其借款新臺幣100 萬元為由，向法院聲請發支付命令獲准，並寄送至乙之戶籍地址，未 據乙提出異議。甲乃執系爭支付命令，聲請執行乙之財產，經執行法院開始強制執行。下列敘述，何 者錯誤？','乙得以其並未住居於系爭支付命令所寄送之戶籍地址，系爭支付命令因未合法送達而失效為由，聲 明異議','乙得以甲並未交付系爭借款，甲之債權不成立為由，提起異議之訴','乙得以其已於強制執行開始後清償系爭借款，甲之債權已消滅為由，提起異議之訴','乙以甲之債權已因抵銷而消滅為由，提起異議之訴，遭駁回確定後，得再以其與甲並無借貸合意， 甲之債權不成立為由，提起異議之訴','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-049','114-4301',49,'single_choice','債權人甲訴請債務人乙將A 土地所有權移轉登記予自己，獲勝訴判決確定後，持該判決聲請執行法 院對乙為強制執行，請求乙辦理所有權移轉登記。關於執行法院之處置，下列敘述，何者正確？','甲未撤回強制執行之聲請時，應裁定駁回','發執行命令，命乙向地政機關辦理及賠償甲代為預納之執行費用','發執行命令，命甲直接向地政機關辦理，並命乙賠償甲代為預納之執行費用','函請地政機關依確定判決辦理，並命乙賠償甲代為預納之執行費用','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-050','114-4301',50,'single_choice','關於金錢請求權之動產與不動產執行程序，下列敘述，何者正確？','兩者均得為強制管理','兩者均須經拍賣程序予以換價','動產拍賣預定有底價者，應於拍賣公告載明','將不動產及其上動產合併拍賣時，適用關於不動產之拍賣規定','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-051','114-4301',51,'single_choice','乙欠甲貨款新臺幣（下同）100 萬元，甲取得確定之支付命令後，執以聲請法院強制執行乙所有之A 車。該車另設定動產抵押權予丙，以擔保丙對乙之120 萬元債權。下列敘述，何者正確？','執行法院查封A 車後，如鑑估其價額為100 萬元，則不必詢問債權人之意見，即可撤銷查封，將A 車返還乙','執行法院查封A 車後，如鑑估其價額為100 萬元，甲仍得聲明於A 車賣得價金不超過120 萬元及 其執行費用時，願負擔其費用，請求繼續拍賣','執行法院於強制執行時，如發現A 車上有丙之抵押權120 萬元，則不得查封A 車','丙對A 車之強制執行程序得提起第三人異議之訴','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('114-4301-052','114-4301',52,'single_choice','債權人甲以債務人乙未依買賣契約移轉A 地所有權，聲請法院對A 地為禁止乙為移轉、設定負擔之 假處分，並據之向執行法院聲請為假處分執行後，乙之另一債權人丙復持同法院命乙給付新臺幣600 萬元本息之確定終局判決，聲請對A 地為終局執行。下列敘述，何者正確？','禁止處分之假處分，僅禁止債務人乙之任意處分，並不禁止強制執行所為之處分，執行法院應准許 丙聲請對A 地之終局執行','A 地既經禁止處分之假處分執行，執行法院應駁回丙聲請對A 地之終局執行','A 地雖經甲聲請為假處分執行，惟丙仍得聲請執行法院對A 地為查封，但不許換價程序','執行法院應裁定命乙提供其他財產供甲擔保後，撤銷對A 地之假處分執行，而准許丙對A 地之終 局執行','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-053','114-4301',53,'single_choice','關於假扣押之執行，下列敘述，何者正確？','假扣押裁定須確定後始能執行','基於假扣押裁定而為執行，法院查封動產後，債務人再處分該動產之行為，絕對無效','對於假扣押之執行，不得藉由聲請假處分而使其停止執行','基於假扣押裁定，執行法院不得發債務人對第三人金錢債權之扣押命令','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-054','114-4301',54,'single_choice','甲列乙為相對人，向法院聲請定暫時狀態處分，命乙容忍甲通行乙所有之A 地獲准。下列敘述，何者 錯誤？','執行法院應將系爭處分送達於乙','甲收受系爭處分已逾30 日後，乙開始妨礙甲通行A 地者，甲仍得執以聲請強制執行','乙設置圍牆妨礙甲通行A 地者，甲得聲請拆除之','系爭處分依乙之抗告經廢棄確定者，執行法院應依乙之聲請，命甲返還通行A 地之利益','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-055','114-4301',55,'single_choice','債權人甲持命乙給付金錢之確定判決，聲請法院執行乙所有之A 地後，丙、丁、戊、己分別提出證明 文件，具狀向執行法院聲明參與分配。下列敘述，何者正確？','丙提出和解筆錄者，如其上所載金錢債權未屆清償期，於聲明參與分配時視同已屆期，丙得參與分配','丁提出禁止處分A 地之假處分者，因其於查封階段與系爭執行程序不相牴觸，故丁得參與分配','戊提出A 地之抵押權設定契約書、他項權利證明書及借據者，雖該等文件並非執行名義，戊仍得參 與分配','己提出乙作為雇主歇業前積欠其3 個月工資之切結書者，雖未取得執行名義，因該工資債權依法有 優先受償之地位，故己得參與分配','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-056','114-4301',56,'single_choice','Under Article 185 of R.O.C. Civil Code, liability is where the whole or a distinct part of the damage suffered by the victim is attributable to two or more persons.','joint and several','discrete','independent','increased','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-057','114-4301',57,'single_choice','Oliver liked to play music extremely loud and it always woke up Mr. and Mrs. Smith at midnight. Oliver was liable to Mr. and Mrs. Smith for .','trespass','nuisance','pain and suffering','mental distress','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-058','114-4301',58,'single_choice','In certain circumstances, A can be held liable for the torts committed by B simply because B is A’s employee or agent or independent contractor, and despite the fact that injury or damage caused by B’s tort may not have been the result of any fault on the part of A. What is the type of the aforementioned tortious liability？','Contributory liability','Vicarious liability','Strict liability','Joint liability','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-059','114-4301',59,'single_choice','is liability regardless of fault. The plaintiff does not have to prove either that the defendant was at fault or that the defendant was not at fault.','Negligent liability','Intentional liability','Strict liability','Inducing liability','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-060','114-4301',60,'single_choice','Adam agreed to sell and Rosa agreed to buy Adam’s house located in Europe. Unfortunately, Adam did not know that his house has burnt down two days ago. Under Article 246 of R.O.C. Civil Code, the contract is .','void','reversible','revocable','unlawful','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('114-4301-061','114-4301',61,'single_choice','When a corporate issuer wishes to raise money and to offer the securities only to professional investors, such as insurance companies or pension funds, etc., outside of a public offering, we call this offering as .','gun-jumping','private placement','public issuance','spin-off','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('114-4301-062','114-4301',62,'single_choice','Which of the following statements regarding sentencing in Taiwan’s Code of Criminal Law is correct?','Both retribution and deterrence are the goals of penalties in Taiwan’s Code of Criminal Law.','Pursuant to Taiwan’s Constitutional Court Ruling, the recidivist must be punished with an enhanced penalty, which might be up to one and a half times the penalty of the offense committed.','Imposing a sentence shall not consider the circumstantial evidence with regard to the defendant’s character, the attitudes after the crime, and the life circumstances.','A probation cannot be imposed with additional condition(s).','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
